package pyz1k.extensions;
import java.util.*;
public final class FunctionDescriptions {
 public record Entry(String id,String title,String text) {}
 private static final Map<String,Entry> ENTRIES;
 static {var entries=new LinkedHashMap<String,Entry>();
  entries.put("Menu",new Entry("Menu","Menu","Открывает главное меню клиента, где включаются функции и настраиваются их параметры и клавиши. По умолчанию меню открывается правым Shift. В настройках Menu можно изменить масштаб интерфейса. Нажми F1 в меню, чтобы открыть эту справку."));
  entries.put("Interface",new Entry("Interface","Interface","Управляет панелями интерфейса клиента и информационной строкой с FPS, пингом, временем и адресом сервера. Можно выбрать нужные показатели, стиль и фон. Поддерживаемые панели можно перемещать в редакторе HUD; настройки отдельных таймеров находятся в соответствующих функциях."));
  entries.put("ItemCooldowns",new Entry("ItemCooldowns","ItemCooldowns","Показывает предметы с активным кулдауном и оставшееся время до следующего использования. Таймеры берутся из данных, которые сервер уже передал клиенту. Если плагин не передаёт свой скрытый кулдаун, эта функция его не угадывает. Можно настроить размер, стиль и фон панели."));
  entries.put("PvPCooldown",new Entry("PvPCooldown","PvPCooldown","Показывает отдельную панель PvP-кулдауна на совместимом сервере. Клиент использует серверную группу кулдауна minecraft:trident, принятую в исходном клиенте. Это не универсальный детектор боевого режима: если сервер не передаёт такой таймер, панель не появляется. Доступны размер, стиль и фон."));
  entries.put("PotionList",new Entry("PotionList","PotionList","Показывает действующие на твоего персонажа эффекты и время до их окончания. Это постоянный список: он помогает следить за силой, скоростью, огнестойкостью и другими эффектами. Можно выбрать обычное или компактное оформление, шрифт, размер и фон. Для отдельного предупреждения перед окончанием эффекта включи EffectAlarm."));
  entries.put("KillEffects",new Entry("KillEffects","KillEffects","Добавляет визуальную анимацию при убийстве, которую рисует твой клиент. Можно выбрать конкретный эффект или случайный вариант и изменить размер анимации. В настройках также есть скрытие некоторых серверных эффектов и звуков. Эти настройки не меняют урон, награды или результат боя."));
  entries.put("ItemSkins",new Entry("ItemSkins","ItemSkins — применение моделей","Включает применение выбранных моделей к твоим предметам. Модели выбираются в каталоге ItemSkin из активного ресурспака сервера. Поддерживаются алмазный и незеритовый мечи, лук, арбалет, тотем и булава. Переключатель «В инвентаре» управляет заменами в твоих слотах. Другие игроки не получают эти визуальные изменения."));
  entries.put("ItemSkin",new Entry("ItemSkin","ItemSkin — каталог моделей","Открывает каталог моделей из активного серверного ресурспака. Сначала зайди на сервер и дождись загрузки его РП, затем выбери материал и модель. Есть поиск, избранное, сохранённые наборы и 3D-просмотр с вращением и масштабированием. Списки разделены по материалам; замена видна только тебе. Здесь же доступны страницы профилей и редактор HUD."));
  entries.put("ClientTools",new Entry("ClientTools","ClientTools — дополнительные страницы","Открывает дополнительные страницы клиента: каталог ItemSkin, сохранённые наборы моделей, серверные профили и редактор HUD. В 26.3 эта кнопка отделена от переключателя ItemSkin, чтобы их состояния правильно сохранялись. Для выбора модели нужен загруженный ресурспак текущего сервера."));
  entries.put("OldMirrorSword",new Entry("OldMirrorSword","OldMirrorSword","Возвращает Зеркальному Мечу и его копиям старую модель clownsword из ресурспака. Клиент распознаёт поддерживаемую модель дзеркалки и подставляет старую только при отрисовке. Серверный предмет, его характеристики и компоненты не изменяются. При одновременной работе с ItemSkin для распознанной дзеркалки приоритет имеет OldMirrorSword."));
  entries.put("LootGloow",new Entry("LootGloow","LootGloow","Подсвечивает лежащий лут и позволяет менять его размер, цвет и дистанцию обработки. Разрешены обычные предметы без нестандартной модели и специальных меток, кастомные тотемы и эпики из белого списка: балиста, незеритовый щит и флейм-арбалет. Легендарные модели и метки имеют приоритет запрета; неизвестные кастомные предметы исключены. Проверяется исходный предмет до замен ItemSkin. Эта функция не управляет подсветкой от сервера или других модов."));
  entries.put("BetterNameVisibility",new Entry("BetterNameVisibility","BetterNameVisibility","Позволяет менять размер, цвет, фон и дистанцию отображения ников игроков. Переключатель «Сквозь стены» разрешает отрисовку ников поверх препятствий. Функция работает с игроками, данные о которых уже есть у клиента: она не ищет людей в незагруженных чанках. Отключи показ сквозь стены, если нужен обычный режим глубины."));
  entries.put("HandRender",new Entry("HandRender","HandRender","Меняет размер и смещение предметов в руках при виде от первого лица. Можно создавать отдельные правила по типу предмета и при необходимости по части его названия. Смещения X, Y и Z помогают убрать крупную модель из центра экрана. Характеристики предмета и размер лежащего лута эта настройка не меняет."));
  entries.put("Cosmetics",new Entry("Cosmetics","Cosmetics","Позволяет выбирать доступные локальные украшения и варианты внешнего вида персонажа. В каталоге есть поиск; для головных украшений можно выбрать показ всегда или только при надетом шлеме. Доступность некоторых моделей зависит от ресурсов клиента и ресурспака. Косметика не выдаёт серверные предметы и не даёт характеристик брони."));
  entries.put("AbilityBind",new Entry("AbilityBind","AbilityBind","Помогает не использовать выбранный предмет случайным нажатием. Создай правило по типу предмета и, если нужно, части названия, затем назначь клавишу. Для подходящего предмета в основной руке клиент разрешает использование только при удержании этой клавиши. Сама клавиша не запускает способность: обычное действие использования всё равно нужно выполнить."));
  entries.put("DurabilityAlert",new Entry("DurabilityAlert","DurabilityAlert","Предупреждает, когда прочность предмета в руке или надетой брони падает до выбранного процента. Порог задаётся в настройках; проверку брони и звук можно включать отдельно. Уведомление показывает предмет и остаток прочности. Это предупреждение, а не автоматическая замена снаряжения."));
  entries.put("BloodSwordCooldown",new Entry("BloodSwordCooldown","BloodSwordCooldown","Показывает известные клиенту таймеры форм и способностей кровавого меча. Выбери режим: Митапы, УхкМитапы, КастомКБ, БыстраяКБ или СМП/ФФА СМП. Пресеты задают параметры режима; оставшееся время берётся из переданных сервером кулдаунов и поддерживаемых меток предмета. Для СМП используются только фактические серверные таймеры. Доступны масштаб, точное время и показ панели без активного КД."));
  entries.put("ReadyAgain",new Entry("ReadyAgain","ReadyAgain","Сообщает, что кулдаун предмета закончился и его снова можно использовать. Сначала предмет должен попасть в наблюдение с активным кулдауном, известным клиенту. После завершения появляется короткая панель; можно настроить её длительность и звук. Скрытые таймеры серверных плагинов без переданных данных не отслеживаются."));
  entries.put("EffectAlarm",new Entry("EffectAlarm","EffectAlarm","Предупреждает перед окончанием эффектов твоего персонажа, например силы или скорости. В настройках выбери, за сколько секунд показывать предупреждение, и нужен ли звук. В панели отображаются название эффекта и оставшееся время. В отличие от PotionList, эта функция предназначена для предупреждения на исходе эффекта."));
  entries.put("RefillReminder",new Entry("RefillReminder","RefillReminder","Напоминает пополнить полезные расходники в хотбаре, когда их осталось мало, но запас ещё есть в основном инвентаре. Проверяются поддерживаемые предметы, включая зелья, жемчуг, золотые яблоки и некоторые другие расходники. Выбери порог количества в настройках. Клиент не перекладывает предметы и не выполняет рефилл автоматически."));
  entries.put("ArmorPanic",new Entry("ArmorPanic","ArmorPanic","Следит за остатком прочности надетой брони и предупреждает при достижении выбранного процента. Панель показывает конкретную часть брони, оставшуюся прочность и её процент. Можно настроить порог, звук и оформление. Броня не снимается и не заменяется автоматически."));
  entries.put("KitCheck",new Entry("KitCheck","KitCheck","Позволяет сохранить текущий комплект как образец и сравнивать с ним содержимое инвентаря и надетую броню. В PvPTools открой настройки функции, сохрани комплект и подтверди изменения кнопкой «Готово». Проверка покажет, каких предметов или частей брони не хватает. Она не выдаёт предметы и не проверяет скрытые серверные свойства комплекта."));
  entries.put("FightRecap",new Entry("FightRecap","FightRecap","Собирает краткие итоги боя: длительность, использованные тобой предметы и срабатывания твоих тотемов. Запись может начаться при полученном клиентом PvP-уроне или вручную назначенной клавишей действия. После завершения доступен отчёт, который можно открыть или сохранить локально. Это журнал наблюдаемых клиентом событий, а не полная серверная статистика боя."));
  entries.put("CombatFocus",new Entry("CombatFocus","CombatFocus","Во время отслеживаемого PvP-боя скрывает второстепенные панели PvP-модулей, чтобы они меньше мешали обзору. В настройках можно также выбрать скрытие таблицы счёта, полос боссов, названия предмета и эффектов Minecraft. Критические предупреждения PvP-модулей остаются видимыми. Режим заканчивается после заданного времени без боевых событий."));
  entries.put("TotemPulse",new Entry("TotemPulse","TotemPulse","После срабатывания твоего тотема ненадолго показывает, сколько тотемов осталось в инвентаре. Событие определяется по сообщению сервера о срабатывании именно у твоего персонажа. Можно выбрать порог малого запаса, звук и оформление панели. Функция не вставляет следующий тотем в руку."));
  entries.put("OffhandAlert",new Entry("OffhandAlert","OffhandAlert","Проверяет, держишь ли ты в левой руке выбранный тип предмета: тотем, щит или золотое яблоко. Если рука пуста или в ней другой предмет, появляется предупреждение. Ожидаемый предмет, звук и оформление задаются в PvPTools. Функция ничего не перекладывает и не выбирает за тебя."));
  entries.put("PearlLandingTimer",new Entry("PearlLandingTimer","PearlLandingTimer","Измеряет полёт твоего жемчуга до столкновения и сохраняет историю бросков. Точное время в тиках доступно только в одиночном мире, где клиенту доступны события встроенного сервера. На многопользовательском сервере функция не угадывает момент приземления. Историю можно открыть через настройки или клавишу действия."));
  entries.put("HotbarMemory",new Entry("HotbarMemory","HotbarMemory","Запоминает, какие предметы должны лежать в каждом из девяти слотов хотбара. Сохрани образец в PvPTools и нажми «Готово»: отличающиеся слоты будут выделяться. Количество предметов и их износ не учитываются; для зелий учитываются данные эффектов. Функция помогает заметить сбитую раскладку, но не сортирует хотбар автоматически."));
  entries.put("PotionIdentity",new Entry("PotionIdentity","PotionIdentity","Рисует короткое обозначение эффекта и его уровня поверх зелий в твоём хотбаре и инвентаре. Например, «С» означает силу, «Б» — скорость, «О» — огнестойкость, «Л» — лечение. Для зелья с несколькими эффектами используется первый распознанный эффект. Полное название и описание зелья остаются в стандартной подсказке Minecraft."));
  entries.put("ResupplyList",new Entry("ResupplyList","ResupplyList","После смерти помогает восстановить заранее сохранённый запас предметов. Сначала сохрани нужный комплект через PvPTools и подтверди его кнопкой «Готово». Затем функция сравнит запас с образцом и покажет недостающее количество. Список также можно открыть вручную; автоматической покупки или выдачи предметов нет."));
  entries.put("DuelNotes",new Entry("DuelNotes","DuelNotes","Позволяет вручную отмечать ошибки и наблюдения после боя: плохой рефилл, забытый эффект, сломанную броню, сбитую раскладку или нехватку ресурсов. Можно добавить собственную короткую заметку. Каждая отметка увеличивает счётчик, а статистика показывает частоту повторений. Клиент не определяет эти ошибки автоматически."));
  entries.put("HudOnDemand",new Entry("HudOnDemand","HudOnDemand","Показывает обычные панели встроенных PvP-модулей при удержании назначенной клавиши. Критические предупреждения продолжают отображаться без удержания. В настройках можно выбрать, какие элементы стандартного HUD скрывать вместе с панелями. Это не переключатель всех возможных оверлеев сторонних модов."));
  entries.put("FightTimeline",new Entry("FightTimeline","FightTimeline","Ведёт последовательную ленту наблюдаемых событий твоего боя: начало записи, использование предметов, срабатывания тотема, смерть и завершение. На экране показываются последние события, полный отчёт можно открыть в настройках и сохранить в файл. Запись начинается при PvP-событии или вручную. Экспорт хранится локально в папке pvp-tools/reports."));
  entries.put("InventorySearchFlash",new Entry("InventorySearchFlash","InventorySearchFlash","Выделяет лечение, броню, жемчуг или предметы по введённому названию и ID. В PvPTools выбери режим «По названию» и введи запрос: несколько слов должны одновременно встречаться в названии или ID предмета. Регистр не учитывается. Можно выделять предметы всё время, пока инвентарь открыт, либо ограничить время. Панель показывает число найденных слотов и общее количество предметов. Проверяются только свои слоты; чужое содержимое и предметы на земле не подсвечиваются."));
  entries.put("PvPTools",new Entry("PvPTools","PvPTools","Открывает подробные настройки семнадцати встроенных PvP-функций. Здесь задаются пороги предупреждений, звук, цвета, масштаб и положение панелей, а также клавиши дополнительных действий. В этом же меню сохраняются комплекты и хотбар, открываются отчёты и заметки. После изменения настроек нажми «Готово», чтобы сохранить их."));
  entries.put("ServerProfiles",new Entry("ServerProfiles","Серверные профили","Сохраняет отдельные состояния функций, настройки, бинды и положение HUD для разных серверов. Автоматические профили включаются на странице профилей в дополнительных инструментах клиента. При переключении сервера клиент сохраняет текущий профиль и восстанавливает подходящий. Общий профиль используется для серверов, у которых ещё нет собственного сохранения."));
  entries.put("HudEditor",new Entry("HudEditor","Редактор HUD","Позволяет мышью перемещать поддерживаемые панели клиента, чтобы они не перекрывали важные части экрана. Открой страницу редактора HUD; некоторые панели также можно перемещать при открытом чате. У новых PvP-панелей свой редактор положения и масштаба находится в PvPTools. Сохраняемое положение относится к панели, а не к игровому миру."));
  entries.put("Configs",new Entry("Configs","Configs — конфиги","Позволяет сохранять и загружать именованные наборы настроек клиента. Это удобно для разных вариантов HUD, клавиш и включённых функций. Сохрани текущий вариант под понятным названием, затем выбирай нужный набор в разделе конфигов. Серверные профили дополнительно автоматизируют переключение настроек при смене сервера."));
  entries.put("Themes",new Entry("Themes","Темы","Меняет цветовое оформление меню и поддерживаемых панелей клиента. Можно выбрать светлую, тёмную или другую доступную тему и настроить цвета. Эти параметры относятся к интерфейсу; они не заменяют текстуры мира, предметов или серверного ресурспака."));
  entries.put("ScreenshotMode",new Entry("ScreenshotMode","ScreenshotMode","Одной клавишей скрывает стандартный игровой HUD и поддерживаемые панели клиента для чистого скриншота. Повторное нажатие восстанавливает предыдущее отображение. По умолчанию назначена F8; клавишу можно изменить в главном меню. Эта функция сама не делает и не сохраняет скриншот."));
  ENTRIES=Collections.unmodifiableMap(entries);
 }
 public static String get(String name,String fallback){var e=ENTRIES.get(name);return e==null?fallback:e.text();}
 public static List<Entry> all(){return List.copyOf(ENTRIES.values());}
 public static String hovered="";
}
